# NOTE: Assertions have been autogenerated by utils/update_mca_test_checks.py
# RUN: llvm-mca -mtriple=aarch64-none-linux-gnu -mcpu=cortex-a53 -iterations=100 -resource-pressure=false -timeline=false -instruction-info=false < %s | FileCheck %s

# FP/ASIMD loads and stores on the Cortex-A53. Measured on hardware, in cycles
# per iteration of each region (all the operands are independent unless the
# region says otherwise):
#
#   ldr d                                1
#   ldr q                                2
#   ldp q                                4
#   ld1 (four Q registers)               8
#   ld4 (.4s)                            8
#   str q                                1
#   stp q                                2
#   st4 (.4s)                            5
#   ldr d + fadd s                       1
#   ldr d + fadd .4s                     2
#   ldr q + add x                        2
#   ldr q + fadd .2s                     2
#   ldr q + fadd .4s                     3
#   ldp s + fadd s                       2
#   ldp q + fadd .4s                     5
#   ld1r (.4s) + fadd s                  2
#   str q + fadd .2s                     1
#   str q + fadd .4s                     2
#   stp q + fadd .4s                     3
#   ldr d, fadd .4s using it             4
#   ldr d, add .4s using it              3
#   ldr q, fadd .4s using it             5
#   ldr q, add .4s using it              4
#   ldr q, str q of it                   4
#   ldp q, fadd .4s using the second     7
#   2 ldr q post-indexed, chained base   6
#   2 str q post-indexed, chained base   4
#   4 fmla .4s + 4 fadd .4s              12
#
# In the last region every fadd waits for the results of the fmlas issued
# before it to be written back; llvm-mca cannot express that.

# LLVM-MCA-BEGIN ldr-d
ldr d16, [sp]
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q
ldr q16, [sp]
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldp-q
ldp q16, q17, [sp]
# LLVM-MCA-END

# LLVM-MCA-BEGIN ld1-4q
ld1 { v16.4s, v17.4s, v18.4s, v19.4s }, [x0]
# LLVM-MCA-END

# LLVM-MCA-BEGIN ld4-4s
ld4 { v16.4s, v17.4s, v18.4s, v19.4s }, [x0]
# LLVM-MCA-END

# LLVM-MCA-BEGIN str-q
str q16, [sp]
# LLVM-MCA-END

# LLVM-MCA-BEGIN stp-q
stp q16, q17, [sp]
# LLVM-MCA-END

# LLVM-MCA-BEGIN st4-4s
st4 { v16.4s, v17.4s, v18.4s, v19.4s }, [x0]
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-d-fadd-s
ldr d16, [sp]
fadd s3, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-d-fadd-4s
ldr d16, [sp]
fadd v3.4s, v1.4s, v2.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-add-x
ldr q16, [sp]
add x1, x1, #1
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-fadd-2s
ldr q16, [sp]
fadd v3.2s, v1.2s, v2.2s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-fadd-4s
ldr q16, [sp]
fadd v3.4s, v1.4s, v2.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldp-s-fadd-s
ldp s16, s17, [sp]
fadd s3, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldp-q-fadd-4s
ldp q16, q17, [sp]
fadd v3.4s, v1.4s, v2.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ld1r-fadd-s
ld1r { v16.4s }, [x0]
fadd s3, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN str-q-fadd-2s
str q16, [sp]
fadd v3.2s, v1.2s, v2.2s
# LLVM-MCA-END

# LLVM-MCA-BEGIN str-q-fadd-4s
str q16, [sp]
fadd v3.4s, v1.4s, v2.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN stp-q-fadd-4s
stp q16, q17, [sp]
fadd v3.4s, v1.4s, v2.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-d-use-fadd
ldr d16, [sp]
fadd v3.4s, v16.4s, v1.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-d-use-add
ldr d16, [sp]
add v3.4s, v16.4s, v1.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-use-fadd
ldr q16, [sp]
fadd v3.4s, v16.4s, v1.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-use-add
ldr q16, [sp]
add v3.4s, v16.4s, v1.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-use-str
ldr q16, [sp]
str q16, [sp, #48]
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldp-q-use-second
ldp q16, q17, [sp]
fadd v3.4s, v17.4s, v1.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN ldr-q-post
ldr q16, [x0], #16
ldr q17, [x0], #-16
# LLVM-MCA-END

# LLVM-MCA-BEGIN str-q-post
str q16, [x0], #16
str q17, [x0], #-16
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmla-fadd
fmla v16.4s, v1.4s, v2.4s
fmla v17.4s, v1.4s, v2.4s
fmla v18.4s, v1.4s, v2.4s
fmla v19.4s, v1.4s, v2.4s
fadd v20.4s, v1.4s, v2.4s
fadd v21.4s, v1.4s, v2.4s
fadd v22.4s, v1.4s, v2.4s
fadd v23.4s, v1.4s, v2.4s
# LLVM-MCA-END

